def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me = history[-1][0]
    last_opp = history[-1][1]

    opp_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1

    opp_rate = opp_d / n

    start = n - 10
    if start < 0:
        start = 0

    recent_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_d += 1

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    my_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'C':
            my_c_streak += 1
        else:
            break

    if opp_d == 0:
        if last_me == 'D' and last_opp == 'C':
            return 'D'
        if last_opp == 'C' and n >= 20:
            return 'D'
        return 'C'

    if last_opp == 'D' and opp_streak == 1 and n <= 2:
        return 'C'

    if opp_rate > 0.55 or recent_d >= 8:
        return 'D'

    if last_opp == 'C':
        return 'C'

    if opp_rate > 0.45 and opp_streak >= 4:
        return 'D'

    if my_c_streak == 1 and opp_streak <= 5 and opp_rate < 0.40:
        return 'C'

    if opp_streak == 1:
        if opp_rate < 0.35 and recent_d <= 2:
            return 'C'
        return 'D'

    if my_d_streak == 1 and opp_streak <= 4 and opp_rate < 0.40:
        return 'C'

    if opp_streak == 2:
        return 'D'

    if my_c_streak >= 2:
        return 'D'

    if opp_streak >= 3:
        return 'D'

    return 'D'
